func pages(url string) func() (Page, bool) {
    next := url
    return func() (Page, bool) {
        if next == "" { return Page{}, false }
        p := fetch(next)                 // computed only when pulled
        next = p.Next
        return p, true
    }
}

next := pages(seed)
for p, ok := next(); ok; p, ok = next() {   // consumer drives demand
    if p.Match { break }                    // early stop, nothing else fetched
}

func Fib(ctx context.Context) <-chan uint64 {
    ch := make(chan uint64)
    go func() {
        defer close(ch)
        for a, b := uint64(0), uint64(1); ; a, b = b, a+b {
            select {
            case ch <- a:                  // demand pulls one element
            case <-ctx.Done():
                return                     // consumer left: stop, no leak
            }
        }
    }()
    return ch
}
